using System;

namespace CrownTowersClub.Models
{
    /// <summary>
    /// Represents a single payment transaction made against a Membership Term.
    /// Maps directly to the [dbo].[Payments] table.
    /// </summary>
    public sealed class Payment
    {
        /* ============================================================
           1. Database Columns (Maps to dbo.Payments)
           ============================================================ */

        /// <summary>
        /// Primary Key. Auto-generated by the database (IDENTITY).
        /// </summary>
        public int PaymentId { get; set; }

        /// <summary>
        /// Foreign Key linking to the specific year/term this payment covers.
        /// </summary>
        public int MembershipTermId { get; set; }

        /// <summary>
        /// The amount paid (e.g., 24.00).
        /// </summary>
        public decimal Amount { get; set; }

        /// <summary>
        /// How the payment was made (Cash, Bank Transfer, Cheque).
        /// </summary>
        public string PaymentMethod { get; set; }

        /// <summary>
        /// When the payment was recorded in the system.
        /// </summary>
        public DateTime PaymentDate { get; set; }

        /// <summary>
        /// Unique identifier printed on the receipt (e.g., RT-2026-0001).
        /// </summary>
        public string ReceiptNumber { get; set; }

        /// <summary>
        /// Optional notes (e.g., "Cheque cleared on 15th").
        /// </summary>
        public string Remarks { get; set; }

        /// <summary>
        /// Audit field. When this row was inserted.
        /// </summary>
        public DateTime CreatedAt { get; set; }


        /* ============================================================
           2. Joined / UI Properties 
           (Populated via SQL INNER JOINs, not stored in the Payments table)
           ============================================================ */

        /// <summary>
        /// The Member ID associated with this payment (Joined from Memberships).
        /// Used by the UI to group payments by member.
        /// </summary>
        public int MemberId { get; set; }

        /// <summary>
        /// The year this payment covers (Joined from MembershipTerms).
        /// Used for filtering and UI display.
        /// </summary>
        public int MembershipYear { get; set; }

        /// <summary>
        /// The applicant's permanent membership number (Joined from Memberships).
        /// Used on the printed receipt.
        /// </summary>
        public string MembershipNumber { get; set; }

        /// <summary>
        /// The applicant's full name (Joined from Members).
        /// Used for display in the Payment History table and on the receipt.
        /// </summary>
        public string Name { get; set; }
    }
}